 90→// TruncateAtUUID returns transcript lines up to and including the line with given UUID
 91→func TruncateAtUUID(lines []TranscriptLine, uuid string) []TranscriptLine {
 92→	if uuid == "" {
 93→		return lines
 94→	}
 95→
 96→	for i, line := range lines {
 97→		if line.UUID == uuid {
 98→			return lines[:i+1]
 99→		}
100→	}
101→
102→	// UUID not found, return full transcript
103→	return lines
104→}
