139→// CalculateTokenUsage calculates token usage from a Claude Code transcript.
140→// This is specific to Claude/Anthropic's API format where each assistant message
141→// contains a usage object with input_tokens, output_tokens, and cache tokens.
142→//
143→// Due to streaming, multiple transcript rows may share the same message.id.
144→// We deduplicate by taking the row with the highest output_tokens for each message.id.
145→func CalculateTokenUsage(transcript []TranscriptLine) *agent.TokenUsage {
146→	// Map from message.id to the usage with highest output_tokens
147→	usageByMessageID := make(map[string]messageUsage)
148→
149→	for _, line := range transcript {
150→		if line.Type != "assistant" {
151→			continue
152→		}
153→
154→		var msg messageWithUsage
155→		if err := json.Unmarshal(line.Message, &msg); err != nil {
156→			continue
157→		}
158→
159→		if msg.ID == "" {
160→			continue
161→		}
162→
163→		// Keep the entry with highest output_tokens (final streaming state)
164→		existing, exists := usageByMessageID[msg.ID]
165→		if !exists || msg.Usage.OutputTokens > existing.OutputTokens {
166→			usageByMessageID[msg.ID] = msg.Usage
167→		}
168→	}
169→
170→	// Sum up all unique messages
171→	usage := &agent.TokenUsage{
172→		APICallCount: len(usageByMessageID),
173→	}
174→	for _, u := range usageByMessageID {
175→		usage.InputTokens += u.InputTokens
176→		usage.CacheCreationTokens += u.CacheCreationInputTokens
177→		usage.CacheReadTokens += u.CacheReadInputTokens
178→		usage.OutputTokens += u.OutputTokens
179→	}
180→
181→	return usage
182→}
183→
184→// CalculateTokenUsageFromFile calculates token usage from a Claude Code transcript file.
185→// If startLine > 0, only considers lines from startLine onwards.
186→func CalculateTokenUsageFromFile(path string, startLine int) (*agent.TokenUsage, error) {
187→	if path == "" {
188→		return &agent.TokenUsage{}, nil
189→	}
190→
191→	lines, err := transcript.ParseFromFileAtLine(path, startLine)
192→	if err != nil {
193→		return nil, err //nolint:wrapcheck // caller adds context
194→	}
195→
196→	return CalculateTokenUsage(lines), nil
197→}
