199→// ExtractSpawnedAgentIDs extracts agent IDs from Task tool results in a transcript.
200→// When a Task tool completes, the tool_result contains "agentId: <id>" in its content.
201→// Returns a map of agentID -> toolUseID for all spawned agents.
202→func ExtractSpawnedAgentIDs(transcript []TranscriptLine) map[string]string {
203→	agentIDs := make(map[string]string)
204→
205→	for _, line := range transcript {
206→		if line.Type != "user" {
207→			continue
208→		}
209→
210→		// Parse as array of content blocks (tool results)
211→		var contentBlocks []struct {
212→			Type      string          `json:"type"`
213→			ToolUseID string          `json:"tool_use_id"`
214→			Content   json.RawMessage `json:"content"`
215→		}
216→
217→		var msg struct {
218→			Content json.RawMessage `json:"content"`
219→		}
220→		if err := json.Unmarshal(line.Message, &msg); err != nil {
221→			continue
222→		}
223→
224→		if err := json.Unmarshal(msg.Content, &contentBlocks); err != nil {
225→			continue
226→		}
227→
228→		for _, block := range contentBlocks {
229→			if block.Type != "tool_result" {
230→				continue
231→			}
232→
233→			// Content can be a string or array of text blocks
234→			var textContent string
235→
236→			// Try as array of text blocks first
237→			var textBlocks []struct {
238→				Type string `json:"type"`
239→				Text string `json:"text"`
240→			}
241→			if err := json.Unmarshal(block.Content, &textBlocks); err == nil {
242→				var textContentSb361 strings.Builder
243→				for _, tb := range textBlocks {
244→					if tb.Type == "text" {
245→						textContentSb361.WriteString(tb.Text + "\n")
246→					}
247→				}
248→				textContent += textContentSb361.String()
249→			} else {
250→				// Try as plain string
251→				var str string
252→				if err := json.Unmarshal(block.Content, &str); err == nil {
253→					textContent = str
254→				}
255→			}
256→
257→			// Look for agentId in the text
258→			if agentID := extractAgentIDFromText(textContent); agentID != "" {
259→				agentIDs[agentID] = block.ToolUseID
260→			}
261→		}
262→	}
263→
264→	return agentIDs
265→}
266→
267→// extractAgentIDFromText extracts an agent ID from text containing "agentId: <id>".
268→func extractAgentIDFromText(text string) string {
269→	const prefix = "agentId: "
270→	idx := strings.Index(text, prefix)
271→	if idx == -1 {
272→		return ""
273→	}
274→
275→	// Extract the ID (alphanumeric characters after the prefix)
276→	start := idx + len(prefix)
277→	end := start
278→	for end < len(text) && (text[end] >= 'a' && text[end] <= 'z' ||
279→		text[end] >= 'A' && text[end] <= 'Z' ||
280→		text[end] >= '0' && text[end] <= '9') {
281→		end++
282→	}
283→
284→	if end > start {
285→		return text[start:end]
286→	}
287→	return ""
288→}
289→
290→// CalculateTotalTokenUsage calculates token usage for a turn, including subagents.
291→// It parses the main transcript bytes from startLine, extracts spawned agent IDs,
292→// and calculates their token usage from transcript files in subagentsDir.
293→func (c *ClaudeCodeAgent) CalculateTotalTokenUsage(transcriptData []byte, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
294→	if len(transcriptData) == 0 {
295→		return &agent.TokenUsage{}, nil
296→	}
297→
298→	// Slice to the relevant portion and parse
299→	sliced := transcript.SliceFromLine(transcriptData, startLine)
300→	parsed, err := transcript.ParseFromBytes(sliced)
301→	if err != nil {
302→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
303→	}
304→
305→	// Calculate token usage from parsed transcript
306→	mainUsage := CalculateTokenUsage(parsed)
307→
308→	// Extract spawned agent IDs from the same parsed transcript
309→	agentIDs := ExtractSpawnedAgentIDs(parsed)
310→
311→	// Calculate subagent token usage (skip when subagentsDir is empty to avoid reading from cwd)
312→	if len(agentIDs) > 0 && subagentsDir != "" {
313→		subagentUsage := &agent.TokenUsage{}
314→		for agentID := range agentIDs {
315→			agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
316→			agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
317→			if err != nil {
318→				// Agent transcript may not exist yet or may have been cleaned up
319→				continue
320→			}
321→			subagentUsage.InputTokens += agentUsage.InputTokens
322→			subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
323→			subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
324→			subagentUsage.OutputTokens += agentUsage.OutputTokens
325→			subagentUsage.APICallCount += agentUsage.APICallCount
326→		}
327→		if subagentUsage.APICallCount > 0 {
328→			mainUsage.SubagentTokens = subagentUsage
329→		}
330→	}
331→
332→	return mainUsage, nil
333→}
334→
335→// ExtractAllModifiedFiles extracts files modified by both the main agent and
336→// any subagents spawned via the Task tool. It parses the main transcript bytes from
337→// startLine, collects modified files from the main agent, then reads each
338→// subagent's transcript from subagentsDir to collect their modified files too.
339→// The result is a deduplicated list of all modified file paths.
340→func (c *ClaudeCodeAgent) ExtractAllModifiedFiles(transcriptData []byte, startLine int, subagentsDir string) ([]string, error) {
341→	if len(transcriptData) == 0 {
342→		return nil, nil
343→	}
344→
345→	// Slice to the relevant portion and parse
346→	sliced := transcript.SliceFromLine(transcriptData, startLine)
347→	parsed, err := transcript.ParseFromBytes(sliced)
348→	if err != nil {
349→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
350→	}
351→
352→	// Collect modified files from main agent
353→	fileSet := make(map[string]bool)
354→	var files []string
355→	for _, f := range ExtractModifiedFiles(parsed) {
356→		if !fileSet[f] {
357→			fileSet[f] = true
358→			files = append(files, f)
359→		}
360→	}
361→
362→	// Find spawned subagents and collect their modified files (skip when subagentsDir is empty to avoid reading from cwd)
363→	agentIDs := ExtractSpawnedAgentIDs(parsed)
364→	if subagentsDir == "" {
365→		return files, nil
366→	}
367→	for agentID := range agentIDs {
368→		agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
369→		agentLines, agentErr := transcript.ParseFromFileAtLine(agentPath, 0)
370→		if agentErr != nil {
371→			// Subagent transcript may not exist yet or may have been cleaned up
372→			continue
373→		}
374→		for _, f := range ExtractModifiedFiles(agentLines) {
375→			if !fileSet[f] {
376→				fileSet[f] = true
377→				files = append(files, f)
378→			}
379→		}
380→	}
381→
382→	return files, nil
383→}
