169→// extractFilePaths extracts file paths from an OpenCode tool's state.
170→// For standard tools (edit, write), the path is in input.filePath or input.path.
171→// For apply_patch (codex models), the paths are in state.metadata.files[].filePath.
172→func extractFilePaths(state *ToolState) []string {
173→	if state == nil {
174→		return nil
175→	}
176→
177→	// Check metadata.files first (used by apply_patch / codex models).
178→	if state.Metadata != nil {
179→		var paths []string
180→		for _, f := range state.Metadata.Files {
181→			if f.FilePath != "" {
182→				paths = append(paths, f.FilePath)
183→			}
184→		}
185→		if len(paths) > 0 {
186→			return paths
187→		}
188→	}
189→
190→	// Fall back to input keys (used by edit, write).
191→	for _, key := range []string{"filePath", "path"} {
192→		if v, ok := state.Input[key]; ok {
193→			if s, ok := v.(string); ok && s != "" {
194→				return []string{s}
195→			}
196→		}
197→	}
198→	return nil
199→}
