 49→// ParseFromFileAtLine reads and parses a transcript file starting from a specific line.
 50→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
 51→// Returns:
 52→//   - lines: parsed transcript lines from startLine onwards (malformed lines skipped)
 53→//   - error: any error encountered during reading
 54→//
 55→// The startLine parameter is 0-indexed (startLine=0 reads from the beginning).
 56→// This is useful for incremental parsing when you've already processed some lines.
 57→func ParseFromFileAtLine(path string, startLine int) ([]Line, error) {
 58→	file, err := os.Open(path) //nolint:gosec // path is a controlled transcript file path
 59→	if err != nil {
 60→		return nil, fmt.Errorf("failed to open transcript: %w", err)
 61→	}
 62→	defer func() { _ = file.Close() }()
 63→
 64→	var lines []Line
 65→	reader := bufio.NewReader(file)
 66→
 67→	totalLines := 0
 68→	for {
 69→		lineBytes, err := reader.ReadBytes('\n')
 70→		if err != nil && err != io.EOF {
 71→			return nil, fmt.Errorf("failed to read transcript: %w", err)
 72→		}
 73→
 74→		// Handle empty line or EOF without content
 75→		if len(lineBytes) == 0 {
 76→			if err == io.EOF {
 77→				break
 78→			}
 79→			continue
 80→		}
 81→
 82→		// Count all lines for totalLines, but only parse after startLine
 83→		if totalLines >= startLine {
 84→			var line Line
 85→			if err := json.Unmarshal(lineBytes, &line); err == nil {
 86→				normalizeLineType(&line)
 87→				lines = append(lines, line)
 88→			}
 89→		}
 90→		totalLines++
 91→
 92→		if err == io.EOF {
 93→			break
 94→		}
 95→	}
 96→
 97→	return lines, nil
 98→}
 99→
100→// normalizeLineType ensures line.Type is populated for all transcript formats.
101→// Claude Code uses "type" while Cursor uses "role" for the same purpose.
102→// When Type is empty but Role is set, we copy Role into Type so all downstream
103→// consumers can switch on Type uniformly.
104→func normalizeLineType(line *Line) {
105→	if line.Type == "" && line.Role != "" {
106→		line.Type = line.Role
107→	}
108→}
109→
110→// SliceFromLine returns the content starting from line number `startLine` (0-indexed).
111→// This is used to extract only the checkpoint-specific portion of a cumulative transcript.
112→// For example, if startLine is 2, lines 0 and 1 are skipped and the result starts at line 2.
113→// Returns empty slice if startLine exceeds the number of lines.
114→func SliceFromLine(content []byte, startLine int) []byte {
115→	if len(content) == 0 || startLine <= 0 {
116→		return content
117→	}
118→
119→	// Find the byte offset where startLine begins
120→	lineCount := 0
121→	offset := 0
122→	for i, b := range content {
123→		if b == '\n' {
124→			lineCount++
125→			if lineCount == startLine {
126→				offset = i + 1
127→				break
128→			}
129→		}
130→	}
131→
132→	// If we didn't find enough lines, return empty
133→	if lineCount < startLine {
134→		return nil
135→	}
136→
137→	// If offset is beyond content, return empty
138→	if offset >= len(content) {
139→		return nil
140→	}
141→
142→	return content[offset:]
143→}
144→
145→// ExtractUserContent extracts user content from a raw message.
146→// Handles both string and array content formats.
147→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
148→// Returns empty string if the message cannot be parsed or contains no text.
149→func ExtractUserContent(message json.RawMessage) string {
150→	var msg UserMessage
151→	if err := json.Unmarshal(message, &msg); err != nil {
152→		return ""
153→	}
154→
155→	// Handle string content
156→	if str, ok := msg.Content.(string); ok {
157→		return textutil.StripIDEContextTags(str)
158→	}
159→
160→	// Handle array content (only if it contains text blocks)
161→	if arr, ok := msg.Content.([]interface{}); ok {
162→		var texts []string
163→		for _, item := range arr {
164→			if m, ok := item.(map[string]interface{}); ok {
165→				if m["type"] == ContentTypeText {
166→					if text, ok := m["text"].(string); ok {
167→						texts = append(texts, text)
168→					}
169→				}
170→			}
171→		}
172→		if len(texts) > 0 {
173→			return textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
174→		}
175→	}
176→
177→	return ""
178→}
