542→
543→	openCodeOpts := CompactOptions{
544→		Agent:      "opencode",
545→		CLIVersion: "0.5.1",
546→		StartLine:  0,
547→	}
548→
549→	expected, err := os.ReadFile("testdata/opencode_expected.jsonl")
550→	if err != nil {
