561→// --- IDE context tag stripping tests ---
562→
563→func TestCompact_StripsIDEContextTags(t *testing.T) {
564→	t.Parallel()
565→
566→	// User text with Cursor's <user_query> tags should have tags stripped.
567→	input := []byte(`{"role":"user","timestamp":"t1","message":{"content":"<user_query>\nhello world\n</user_query>"}}
568→`)
569→
570→	cursorOpts := CompactOptions{
571→		Agent:      "cursor",
572→		CLIVersion: "0.5.1",
573→		StartLine:  0,
574→	}
575→
576→	expected := []string{
577→		`{"v":1,"agent":"cursor","cli_version":"0.5.1","type":"user","ts":"t1","content":"hello world"}`,
578→	}
579→
580→	result, err := Compact(input, cursorOpts)
