591→	input := []byte(`{"type":"user","timestamp":"t1","message":{"content":[{"type":"text","text":"<user_query>\nfix the bug\n</user_query>"},{"type":"text","text":"also this"}]}}
592→`)
593→
594→	expected := []string{
595→		`{"v":1,"agent":"claude-code","cli_version":"0.5.1","type":"user","ts":"t1","content":"fix the bug\n\nalso this"}`,
596→	}
