605→// --- Helpers ---
606→
607→func nonEmptyLines(data []byte) []string {
608→	var lines []string
609→	for _, line := range strings.Split(string(data), "\n") {
610→		if strings.TrimSpace(line) != "" {
611→			lines = append(lines, line)
612→		}
613→	}
614→	return lines
615→}
616→
617→// assertJSONLines compares actual output lines against expected JSON strings,
618→// using semantic JSON equality (order-independent for object keys).
619→func assertJSONLines(t *testing.T, actual []byte, expected []string) {
620→	t.Helper()
621→
622→	actualLines := nonEmptyLines(actual)
623→
624→	if len(expected) == 0 && len(actualLines) == 0 {
625→		return
626→	}
627→
628→	if len(actualLines) != len(expected) {
629→		t.Fatalf("line count mismatch: got %d, want %d\nactual:\n%s", len(actualLines), len(expected), string(actual))
630→	}
631→
632→	for i := range expected {
633→		var got, want interface{}
634→		if err := json.Unmarshal([]byte(actualLines[i]), &got); err != nil {
635→			t.Fatalf("line %d: failed to parse actual JSON: %v\nline: %s", i, err, actualLines[i])
636→		}
637→		if err := json.Unmarshal([]byte(expected[i]), &want); err != nil {
638→			t.Fatalf("line %d: failed to parse expected JSON: %v\nline: %s", i, err, expected[i])
639→		}
640→		if !reflect.DeepEqual(got, want) {
641→			prettyGot, _ := json.MarshalIndent(got, "", "  ")
642→			prettyWant, _ := json.MarshalIndent(want, "", "  ")
643→			t.Errorf("line %d mismatch:\ngot:\n%s\nwant:\n%s", i, prettyGot, prettyWant)
644→		}
645→	}
646→}
