	t.Parallel()

	input := []byte(`{"type":"user","uuid":"u1","timestamp":"t1","message":{"content":"hello"}}` + "\n")
	opts := CompactOptions{Agent: "claude-code", CLIVersion: "0.5.1", StartLine: 100}

	result, err := Compact(input, opts)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
