 15→// droppedTypes are entry types that carry no parser-relevant data.
 16→var droppedTypes = map[string]bool{
 17→	"progress":              true,
 18→	"file-history-snapshot": true,
 19→	"queue-operation":       true,
 20→	"system":                true,
 21→}
 22→
 23→// CompactOptions provides metadata fields written to every output line.
 24→type CompactOptions struct {
 25→	Agent      string // e.g. "claude-code"
 26→	CLIVersion string // e.g. "0.42.0"
 27→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 28→}
 29→
 30→// compactMeta holds pre-computed JSON fragments for fields that are identical
 31→// on every output line, avoiding repeated marshaling.
 32→type compactMeta struct {
 33→	v          json.RawMessage
 34→	agent      json.RawMessage
 35→	cliVersion json.RawMessage
 36→}
 37→
 38→func newCompactMeta(opts CompactOptions) compactMeta {
 39→	return compactMeta{
 40→		v:          mustMarshal(1),
 41→		agent:      mustMarshal(opts.Agent),
 42→		cliVersion: mustMarshal(opts.CLIVersion),
 43→	}
 44→}
 45→
 46→// Compact converts a full.jsonl transcript into the transcript.jsonl format.
 47→//
 48→// The output format puts version, agent, and cli_version on every line,
 49→// flattens the message wrapper, and splits user tool results into separate entries:
 50→//
 51→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 52→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user_tool_result","ts":"...","tool_use_id":"...","result":{...}}
 53→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[...]}
 54→func Compact(content []byte, opts CompactOptions) ([]byte, error) {
 55→	truncated := SliceFromLine(content, opts.StartLine)
 56→	if truncated == nil {
 57→		truncated = []byte{}
 58→	}
 59→
 60→	// Detect OpenCode format: a single JSON object with "info" and "messages" keys.
 61→	if isOpenCodeFormat(truncated) {
 62→		return compactOpenCode(truncated, opts)
 63→	}
 64→
 65→	meta := newCompactMeta(opts)
 66→	reader := bufio.NewReader(bytes.NewReader(truncated))
 67→	var result []byte
 68→
 69→	for {
 70→		lineBytes, err := reader.ReadBytes('\n')
 71→		if err != nil && err != io.EOF {
 72→			return nil, err
 73→		}
 74→
 75→		if len(bytes.TrimSpace(lineBytes)) > 0 {
 76→			outputLines := convertLine(lineBytes, meta)
 77→			for _, ol := range outputLines {
 78→				result = append(result, ol...)
 79→				result = append(result, '\n')
 80→			}
 81→		}
 82→
 83→		if err == io.EOF {
 84→			break
 85→		}
 86→	}
 87→
 88→	return result, nil
 89→}
 90→
 91→// userAliases maps transcript type/role values to the canonical "user" kind.
 92→var userAliases = map[string]bool{
 93→	TypeUser: true,
 94→	"human":  true,
 95→}
 96→
 97→// assistantAliases maps transcript type/role values to the canonical "assistant" kind.
 98→var assistantAliases = map[string]bool{
 99→	TypeAssistant: true,
100→	"gemini":      true,
101→}
102→
103→// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
104→// transcript line. It checks the "type" field, then falls back to "role".
105→// Returns "" for unrecognised or dropped entries.
106→func normalizeKind(raw map[string]json.RawMessage) string {
107→	kind := unquote(raw["type"])
108→	if kind == "" {
109→		kind = unquote(raw["role"])
110→	}
111→
112→	if droppedTypes[kind] {
113→		return ""
114→	}
115→	if userAliases[kind] {
116→		return TypeUser
117→	}
118→	if assistantAliases[kind] {
119→		return TypeAssistant
120→	}
121→	return ""
122→}
123→
124→// unwrapEnvelope handles envelope formats where the actual message is nested.
125→// Factory AI Droid uses {"type":"message","message":{"role":"user","content":...}}.
126→// If the line is an envelope, it promotes inner fields (role, content) to the top
127→// level and carries over outer fields (timestamp, id) so converters see a flat structure.
128→// Otherwise it returns raw unchanged.
129→func unwrapEnvelope(raw map[string]json.RawMessage) map[string]json.RawMessage {
130→	if unquote(raw["type"]) != "message" {
131→		return raw
132→	}
133→
134→	msgRaw, ok := raw["message"]
135→	if !ok {
136→		return raw
137→	}
138→
139→	var inner map[string]json.RawMessage
140→	if json.Unmarshal(msgRaw, &inner) != nil {
141→		return raw
142→	}
143→
144→	innerRole := unquote(inner["role"])
145→	if !userAliases[innerRole] && !assistantAliases[innerRole] {
146→		return raw
147→	}
148→
149→	// Merge outer → inner: outer timestamp/id as defaults, inner fields override.
150→	merged := make(map[string]json.RawMessage, len(inner)+3)
151→	if v, has := raw["timestamp"]; has {
152→		merged["timestamp"] = v
153→	}
154→	if v, has := raw["id"]; has {
155→		merged["id"] = v
156→	}
157→	for k, v := range inner {
158→		merged[k] = v
159→	}
160→	// Promote "role" to "type" so normalizeKind resolves it.
161→	if _, hasType := merged["type"]; !hasType {
162→		merged["type"] = inner["role"]
163→	}
164→	// Keep "message" so converters can extract nested content.
165→	merged["message"] = msgRaw
166→
167→	return merged
168→}
169→
170→// convertLine converts a single full.jsonl line into zero or more transcript.jsonl lines.
171→func convertLine(lineBytes []byte, meta compactMeta) [][]byte {
172→	var raw map[string]json.RawMessage
173→	if err := json.Unmarshal(lineBytes, &raw); err != nil {
174→		return nil
175→	}
176→
177→	raw = unwrapEnvelope(raw)
178→
179→	switch normalizeKind(raw) {
180→	case TypeAssistant:
181→		return convertAssistant(raw, meta)
182→	case TypeUser:
183→		return convertUser(raw, meta)
184→	default:
185→		return nil
186→	}
187→}
188→
189→func convertAssistant(raw map[string]json.RawMessage, meta compactMeta) [][]byte {
190→	var id, content json.RawMessage
191→	if msg := parseMessage(raw); msg != nil {
192→		id = msg["id"]
193→		if contentRaw, ok := msg["content"]; ok {
194→			content = stripAssistantContent(contentRaw)
195→		}
196→	}
197→
198→	b := marshalOrdered(
199→		"v", meta.v,
200→		"agent", meta.agent,
201→		"cli_version", meta.cliVersion,
202→		"type", mustMarshal(TypeAssistant),
203→		"ts", raw["timestamp"],
204→		"id", id,
205→		"content", content,
206→	)
207→	if b == nil {
208→		return nil
209→	}
210→	return [][]byte{b}
211→}
212→
213→func convertUser(raw map[string]json.RawMessage, meta compactMeta) [][]byte {
214→	var lines [][]byte
215→	ts := raw["timestamp"]
216→
217→	var textContent string
218→	var toolResults []toolResultEntry
219→
220→	if msg := parseMessage(raw); msg != nil {
221→		if contentRaw, ok := msg["content"]; ok {
222→			textContent, toolResults = extractUserContent(contentRaw)
223→		}
224→	}
225→
226→	b := marshalOrdered(
227→		"v", meta.v,
228→		"agent", meta.agent,
229→		"cli_version", meta.cliVersion,
230→		"type", mustMarshal(TypeUser),
231→		"ts", ts,
232→		"content", mustMarshal(textContent),
233→	)
234→	if b != nil {
235→		lines = append(lines, b)
236→	}
237→
238→	// full.jsonl has a single toolUseResult per user entry, not one per tool_use_id.
239→	// When there are multiple tool_result blocks, each user_tool_result line gets the
240→	// same minimized result — a known limitation of the source format.
241→	var minimizedResult json.RawMessage
242→	if turRaw, ok := raw["toolUseResult"]; ok {
243→		minimizedResult = minimizeToolUseResult(turRaw)
244→	}
245→
246→	for _, tr := range toolResults {
247→		result := minimizedResult
248→		if result == nil {
249→			result = mustMarshal(map[string]interface{}{})
250→		}
251→
252→		b := marshalOrdered(
253→			"v", meta.v,
254→			"agent", meta.agent,
255→			"cli_version", meta.cliVersion,
256→			"type", mustMarshal("user_tool_result"),
257→			"ts", ts,
258→			"tool_use_id", mustMarshal(tr.toolUseID),
259→			"result", result,
260→		)
261→		if b != nil {
262→			lines = append(lines, b)
263→		}
264→	}
265→
266→	return lines
267→}
