435→// --- OpenCode format support ---
436→//
437→// OpenCode transcripts are a single JSON object (not JSONL):
438→//
439→//	{"info":{...},"messages":[{"info":{"role":"user","time":{...}},"parts":[...]}, ...]}
440→//
441→// Parts use "type" values: "text", "tool", "step-start", "step-finish".
442→// Tool parts store the tool name in "tool" (string) and call details in "state".
443→
444→// isOpenCodeFormat checks whether content is a single JSON object with the
445→// OpenCode session shape (top-level "info" and "messages" keys).
446→func isOpenCodeFormat(content []byte) bool {
447→	trimmed := bytes.TrimSpace(content)
448→	if len(trimmed) == 0 || trimmed[0] != '{' {
449→		return false
450→	}
451→	// Quick structural check: unmarshal just enough to detect the keys.
452→	var probe struct {
453→		Info     *json.RawMessage `json:"info"`
454→		Messages *json.RawMessage `json:"messages"`
455→	}
456→	if json.Unmarshal(trimmed, &probe) != nil {
457→		return false
458→	}
459→	return probe.Info != nil && probe.Messages != nil
460→}
